    private static final Logger LOGGER = Logger.getLogger(FileService.class.getName());
    private static final String BASE_DIRECTORY = "/tmp/upload/";

    /**
     * Reads the content of a file specified by the file path.
     * The file path is relative to the /tmp/upload/ directory.
     *
     * @param filePath the relative path to the file within /tmp/upload/
     * @return the complete content of the file as a string
     * @throws IOException if the file does not exist, cannot be read, or an I/O error occurs
     */
    public String readFileContent(String filePath) throws IOException {
        if (filePath == null || filePath.trim().isEmpty()) {
            throw new IOException("File path cannot be null or empty");
        }

        // Normalize the file path to prevent directory traversal
        String normalizedPath = filePath.replace('\\', '/');
        if (normalizedPath.startsWith("/")) {
            normalizedPath = normalizedPath.substring(1);
        }

        // Construct the full path
        Path fullPath = Paths.get(BASE_DIRECTORY, normalizedPath).normalize();

        // Security check: ensure the resolved path is within the base directory
        if (!fullPath.startsWith(Paths.get(BASE_DIRECTORY).normalize())) {
            throw new IOException("Access denied: file path is outside the allowed directory");
        }

        // Check if the file exists
        if (!Files.exists(fullPath)) {
            throw new IOException("File not found: " + fullPath.toString());
        }

        // Check if the path is a regular file
        if (!Files.isRegularFile(fullPath)) {
            throw new IOException("Path is not a regular file: " + fullPath.toString());
        }

        // Check if the file is readable
        if (!Files.isReadable(fullPath)) {
            throw new IOException("File is not readable: " + fullPath.toString());
        }

        LOGGER.log(Level.INFO, "Reading file: {0}", fullPath.toString());

        // Read the file content using BufferedReader with UTF-8 encoding
        StringBuilder contentBuilder = new StringBuilder();
        try (BufferedReader reader = Files.newBufferedReader(fullPath, StandardCharsets.UTF_8)) {
            String line;
            boolean firstLine = true;
            while ((line = reader.readLine()) != null) {
                if (!firstLine) {
                    contentBuilder.append(System.lineSeparator());
                }
                contentBuilder.append(line);
                firstLine = false;
            }
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Failed to read file: " + fullPath.toString(), e);
            throw new IOException("Failed to read file: " + fullPath.toString(), e);
        }

        LOGGER.log(Level.INFO, "Successfully read file: {0}", fullPath.toString());
        return contentBuilder.toString();
    }
}
